# Tool execution reliability: Timeout Enforcement
import time
attempts = 0
def flaky():
    global attempts; attempts += 1
    if attempts < 3:
        raise TimeoutError("timeout")
    return "ok"
for i in range(5):
    try:
        print("result:", flaky()); break
    except TimeoutError:
        time.sleep(0.01 * (2 ** i))
print("technique: deadline per call - mitigates hang;infinite loop")

